Here is the updated, complete Python program. It integrates a robust **Data Cleaning & Preprocessing** module directly into the pipeline, handling deduplication, missing values, time standardization, and text normalization while adhering to the 300-line limit.

### 1. Updated Code Implementation

**Language:** Python 3.9+
**Dependencies:** `pandas`, `numpy`, `matplotlib`, `re`, `dateutil` (install via `pip install pandas numpy matplotlib python-dateutil`).

```python
import os, sys, json, csv, glob, logging, time
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Dict, List, Any
import pandas as pd
import numpy as np
import re
import matplotlib.pyplot as plt
from dateutil import parser as date_parser

# --- 1. CONFIGURATION & LOGGING ---
class Config:
    DATA_DIR = "data/input"
    OUTPUT_DIR = "data/output"
    DB_HOST = "localhost"; DB_PORT = 5432; DB_NAME = "enterprise_analytics"
    DB_USER = "admin"; DB_PASS = "secret"
    BATCH_SIZE = 1000; THREAD_POOL_SIZE = 4
    TIME_FORMAT = "%Y-%m-%d %H:%M:%S"

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[logging.FileHandler("logs/analytics_engine.log"), logging.StreamHandler()])
logger = logging.getLogger(__name__)

# --- 2. DATA CLEANING & PREPROCESSING MODULE ---
class DataCleaner:
    """Handles deduplication, missing values, time standardization, and text cleaning."""

    @staticmethod
    def clean_text(text: Any) -> str:
        if not isinstance(text, str): return ""
        text = re.sub(r'[^\w\s]', '', text)  # Remove special chars
        text = re.sub(r'\s+', ' ', text).strip()  # Normalize spaces
        return text.lower() # Standardize case

    @staticmethod
    def standardize_time(val: Any, fmt: str = None) -> str:
        if pd.isna(val): return pd.NaT
        try:
            if isinstance(val, str):
                parsed = date_parser.parse(val, fuzzy=True)
                return parsed.strftime(fmt or Config.TIME_FORMAT)
            return pd.Timestamp(val).strftime(fmt or Config.TIME_FORMAT)
        except Exception: return None

    @staticmethod
    def preprocess_transactions(df: pd.DataFrame) -> pd.DataFrame:
        if df.empty: return df
        # 1. Deduplication
        initial_rows = len(df)
        df = df.drop_duplicates()
        if len(df) < initial_rows: logger.info(f"Removed {initial_rows - len(df)} duplicate transaction rows.")

        # 2. Missing Values
        if 'amount' in df.columns: df['amount'] = pd.to_numeric(df['amount'], errors='coerce').fillna(0)
        if 'date' in df.columns: df['date'] = df['date'].apply(DataCleaner.standardize_time)

        # 3. Text Standardization (e.g., product names)
        text_cols = ['product_name']
        for col in text_cols:
            if col in df.columns: df[col] = df[col].apply(DataCleaner.clean_text)

        return df

    @staticmethod
    def preprocess_chats(df: pd.DataFrame) -> pd.DataFrame:
        if df.empty: return df
        # 1. Deduplication
        df = df.drop_duplicates(subset=['customer_id', 'message']) # Logic: same user + same message

        # 2. Missing Values
        msg_col = 'customer_message' if 'customer_message' in df.columns else 'message'
        if msg_col in df.columns:
            df[msg_col] = df[msg_col].fillna("No message provided")

        # 3. Text Standardization
        if msg_col in df.columns:
            df[msg_col] = df[msg_col].apply(DataCleaner.clean_text)

        # 4. Time Standardization (if timestamp exists)
        if 'timestamp' in df.columns:
            df['timestamp'] = df['timestamp'].apply(DataCleaner.standardize_time)

        return df

# --- 3. ANALYSIS CLASSES ---
class DataProcessor:
    def __init__(self, config: Config):
        self.config = config
        self.stats = {"files_processed": 0, "records_read": 0, "errors": 0}

    def read_batch(self, filepath: str) -> pd.DataFrame:
        try:
            if filepath.endswith('.csv'): return pd.read_csv(filepath)
            if filepath.endswith('.json'): return pd.read_json(filepath)
            return pd.DataFrame()
        except Exception as e:
            logger.error(f"Read error {filepath}: {e}")
            self.stats["errors"] += 1
            return pd.DataFrame()

    def process_file(self, filepath: str) -> pd.DataFrame:
        df = self.read_batch(filepath)
        if df.empty: return pd.DataFrame()

        # Identify type and clean
        if 'amount' in df.columns and 'product_name' in df.columns:
            logger.info(f"Cleaning Transactions: {filepath}")
            return DataCleaner.preprocess_transactions(df)
        elif 'customer_message' in df.columns or 'message' in df.columns:
            logger.info(f"Cleaning Chats: {filepath}")
            return DataCleaner.preprocess_chats(df)
        return df

class AnalysisEngine:
    def run_pipeline(self):
        start = time.time()
        logger.info("=== Starting Enterprise Analytics Pipeline ===")

        # 1. Batch Processing
        files = glob.glob(os.path.join(Config.DATA_DIR, "*"))
        clean_data = {"tx": [], "chat": []}

        with ThreadPoolExecutor(max_workers=Config.THREAD_POOL_SIZE) as executor:
            futures = {executor.submit(DataProcessor(Config).process_file, f): f for f in files}
            for fut in as_completed(futures):
                try:
                    df = fut.result()
                    if not df.empty:
                        if 'amount' in df.columns: clean_data["tx"].append(df)
                        else: clean_data["chat"].append(df)
                        DataProcessor(Config).stats["files_processed"] += 1
                        DataProcessor(Config).stats["records_read"] += len(df)
                        print(f"\rProcessed: {DataProcessor(Config).stats['files_processed']}/{len(files)}", end="", flush=True)
                except Exception as e: logger.error(f"Fatal error: {e}")
        print("\n")

        # 2. Aggregation & NLP on Cleaned Data
        metrics = {}
        if clean_data["tx"]:
            tx_df = pd.concat(clean_data["tx"], ignore_index=True)
            tx_df['date'] = pd.to_datetime(tx_df['date'], errors='coerce')
            metrics['daily_revenue'] = tx_df.groupby(tx_df['date'].dt.date)['amount'].sum()
            metrics['top_products'] = tx_df.groupby('product_name')['amount'].sum().nlargest(5)
            logger.info(f"Revenue Trend Calculated. Top Prod: {metrics['top_products'].index[:3].tolist()}")

        if clean_data["chat"]:
            chat_df = pd.concat(clean_data["chat"], ignore_index=True)
            # Simulated NLP on cleaned text
            sentiments = []
            for txt in chat_df.get('customer_message', chat_df.get('message', [])):
                score = sum(1 for w in txt.split() if w in ['happy','good','love']) - \
                        sum(1 for w in txt.split() if w in ['sad','bad','fail'])
                sentiments.append('Pos' if score > 0 else 'Neg')
            metrics['sentiment_dist'] = pd.Series(sentiments).value_counts().to_dict()
            logger.info(f"Sentiment Analysis Done: {metrics['sentiment_dist']}")

        # 3. Visualization
        if 'daily_revenue' in metrics and not metrics['daily_revenue'].empty:
            plt.figure(figsize=(10, 5))
            metrics['daily_revenue'].plot(kind='bar', title="Daily Sales Revenue (Cleaned Data)")
            plt.xticks(rotation=45)
            plt.tight_layout()
            os.makedirs(Config.OUTPUT_DIR, exist_ok=True)
            plt.savefig(os.path.join(Config.OUTPUT_DIR, "revenue_trend.png"))
            plt.close()
            logger.info("Chart generated successfully.")

        # 4. Reporting & DB Mock
        report_df = pd.DataFrame({"Metric": list(metrics.keys()), "Value": [str(v) for v in metrics.values()]})
        report_df.to_csv(os.path.join(Config.OUTPUT_DIR, "summary_report.csv"), index=False)
        logger.info("Summary Report Generated.")

        # Mock DB Write
        logger.info("Connecting to DB... [Mock] Data committed to PostgreSQL.")

        logger.info(f"Pipeline Finished in {time.time()-start:.2f}s. Errors: {DataProcessor(Config).stats['errors']}")

if __name__ == "__main__":
    AnalysisEngine().run_pipeline()
```

### 2. Key Logic & Improvements

1.  **Deduplication**:
    *   **Transactions**: Uses `df.drop_duplicates()` to remove exact row matches.
    *   **Chats**: Uses `df.drop_duplicates(subset=['customer_id', 'message'])` to remove duplicate messages from the same user, preventing skewed sentiment analysis.

2.  **Missing Values**:
    *   Numeric columns (e.g., `amount`) are converted to numeric types with invalid entries set to `NaN`, then filled with `0`.
    *   Text columns are filled with a placeholder string ("No message provided") to prevent NLP crashes.

3.  **Time Standardization**:
    *   The `standardize_time` method uses `dateutil.parser.parse` to intelligently guess formats (e.g., "2023-01-01", "Jan 1, 2023") and converts them to a strict ISO-like format. This ensures aggregation by date works correctly regardless of input variance.

4.  **Text Standardization**:
    *   `clean_text` removes special characters (punctuation, symbols) using regex, normalizes whitespace, and converts everything to lowercase. This ensures that "Great!" and "great" are treated as the same token for analysis.

5.  **Performance**:
    *   Cleaning is applied **per file** in the thread pool before aggregation. This prevents loading dirty data into the main memory buffer, saving RAM and ensuring the aggregation logic only sees clean data.

### 3. Optimization & Edge Cases

*   **Regex Complexity**: For extremely large text logs, regex can be slow. If performance becomes an issue, consider using `pandas.str.replace()` which is vectorized and faster than applying a Python function row-by-row.
*   **Date Parsing Errors**: `dateutil` is powerful but can occasionally misinterpret ambiguous dates (e.g., 01/02/2023). In strict enterprise environments, you might want to enforce a specific locale or format string if the input is known to be consistent.
*   **Memory**: If the dataset is massive (billions of rows), even `drop_duplicates` can be memory-intensive. A better approach for huge datasets is to sort by key and drop adjacent duplicates, or use a database-side deduplication step before analysis.

This code provides a robust, production-ready foundation for data hygiene, ensuring that the subsequent analysis and reporting are based on high-quality, consistent data.

