// --- Configuration ---
struct Config {
    std::string dataDir = "data/input";
    std::string outDir = "data/output";
    int threads = 4;
    std::string timeFormat = "%Y-%m-%d %H:%M:%S";
};

// --- Data Structures ---
struct Transaction {
    std::string date;
    std::string product;
    double amount;
};

struct ChatMessage {
    std::string user;
    std::string message;
};

// --- Utility: Text Cleaning & Standardization ---
class DataCleaner {
public:
    static std::string cleanText(const std::string& text) {
        if (text.empty()) return "";
        std::string res;
        for (char c : text) {
            if (std::isalnum(c) || std::isspace(c)) res += std::tolower(c);
        }
        // Normalize spaces
        std::string clean;
        char prev = 0;
        for (char c : res) {
            if (c == ' ' && prev == ' ') continue;
            clean += c;
            prev = c;
        }
        if (!clean.empty() && clean.back() == ' ') clean.pop_back();
        return clean;
    }

    static std::string standardizeTime(const std::string& raw) {
        // Simplified logic: In production, use a library like ICU or Boost.Date_Time
        // Assuming input is roughly YYYY-MM-DD...
        if (raw.length() >= 10) return raw.substr(0, 10);
        return raw;
    }
};

// --- Shared State for Thread Safety ---
struct GlobalStats {
    std::mutex mtx;
    int filesProcessed = 0;
    int recordsRead = 0;
    int errors = 0;
    std::vector<Transaction> txData;
    std::vector<ChatMessage> chatData;
};

// --- Worker: Process File (Mocked for Demo) ---
void processFile(const std::string& filePath, GlobalStats& stats) {
    std::lock_guard<std::mutex> lock(stats.mtx);

    // Simulate file reading logic (In real C++, use fopen/fread or libraries)
    // We simulate 5 random records per file for demonstration
    int simulatedRecords = 5; 

    for (int i = 0; i < simulatedRecords; ++i) {
        // Mock Transaction
        if (true) { // Logic to distinguish types
            Transaction t;
            t.date = "2023-10-0" + std::to_string(i % 30 + 1); // Mock date
            t.product = DataCleaner::cleanText("Product_A");
            t.amount = 10.0 + i * 2.5;
            stats.txData.push_back(t);
        }
    }

    // Mock Chat
    ChatMessage cm;
    cm.user = "user_1";
    cm.message = DataCleaner::cleanText("Product is great but shipping is bad!");
    stats.chatData.push_back(cm);

    stats.filesProcessed++;
    stats.recordsRead += simulatedRecords;

    std::cout << "\rProcessed: " << stats.filesProcessed << " files | " 
              << stats.recordsRead << " records read" << std::flush;
}

// --- Analysis & Aggregation ---
void analyzeData(const GlobalStats& stats) {
    std::cout << "\n=== Aggregation & Analysis ===\n";

    // 1. Transaction Aggregation (Revenue by Product)
    std::map<std::string, double> revenueMap;
    for (const auto& t : stats.txData) {
        revenueMap[t.product] += t.amount;
    }

    std::cout << "Top Products (Cleaned Data):\n";
    // Sort and print top 3
    std::vector<std::pair<std::string, double>> sortedRev(revenueMap.begin(), revenueMap.end());
    std::sort(sortedRev.begin(), sortedRev.end(), 
              [](const auto& a, const auto& b){ return a.second > b.second; });

    int count = 0;
    for (const auto& p : sortedRev) {
        if (count++ > 4) break;
        std::cout << "  " << p.first << ": $" << std::fixed << std::setprecision(2) << p.second << "\n";
    }

    // 2. Sentiment Analysis (Mock)
