    for (const auto& m : stats.chatData) {
        std::string msg = m.message;
        if (msg.find("great") != std::string::npos || msg.find("good") != std::string::npos) pos++;
        if (msg.find("bad") != std::string::npos || msg.find("fail") != std::string::npos) neg++;
    }
    std::cout << "Sentiment: Pos=" << pos << ", Neg=" << neg << "\n";
}

// --- Main Pipeline ---
int main() {
    Config cfg;
