    std::vector<std::string> mockFiles = {"data1.csv", "data2.json", "data3.csv"};

    std::vector<std::thread> threads;
    for (const auto& file : mockFiles) {
        threads.emplace_back(processFile, file, std::ref(stats));
    }

    for (auto& t : threads) t.join();

